Q_OUT=$(q_live backlinks nonexistent-slug-xyz 2>&1); Q_RC=$?
if [ "$Q_RC" = "4" ] && echo "$Q_OUT" | grep -q "not found" \
   && echo "$Q_OUT" | grep -q '"error": "query-input"'; then
