import json, sys
d = json.loads('''$Q_OUT''')
req = {'total_nodes', 'by_status', 'by_domain', 'top_blocking', 'top_longest_deferred', 'avg_dep_depth', 'orphan_count'}
missing = req - set(d.keys())
sys.exit(1 if missing else 0)
