Q_OUT=$(python3 "$QUERY_PY" --cache "$SCALAR_TREE/cache.json" --repo-root "$SCALAR_TREE" --quiet stats --json 2>&1); Q_RC=$?
if [ "$Q_RC" = "2" ] && echo "$Q_OUT" | grep -q "cache-unusable"; then
