DUPID_OUT=$(python3 "$QUERY_PY" --cache "$DUPID_TREE/dup.json" --repo-root "$DUPID_TREE" --quiet blocking --json 2>&1); DUPID_RC=$?
bind_baseline "$DUPID_TREE/nulls.json"
